import urllib.request, urllib.parse, json, re, sys, time

ids=[x.strip().upper() for x in open('/app/pdb_ids.txt') if x.strip()]
print('PDB IDs:', ids, flush=True)

# Save full FASTA for all PDB IDs
fastas={}
for pid in ids:
    url=f'https://www.rcsb.org/fasta/entry/{pid}'
    try:
        req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
        data=urllib.request.urlopen(req, timeout=20).read().decode('utf-8','replace')
        fastas[pid]=data
        seqs=[s.split('\n',1)[1].replace('\n','') for s in data.strip().split('>') if s.strip()]
        print(pid, 'seqs:', [len(s) for s in seqs], flush=True)
    except Exception as e:
        print('FASTA ERR', pid, repr(e), flush=True)

with open('/tmp/pdb_fastas.txt','w') as f:
    for pid,data in fastas.items():
        f.write(data)
print('Saved /tmp/pdb_fastas.txt', flush=True)

# Parse FPbase proteins
url='https://www.fpbase.org/api/proteins/?format=json'
req=urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'})
raw=urllib.request.urlopen(req, timeout=60).read().decode('utf-8','replace')
print('FPbase proteins len', len(raw), flush=True)
prots=json.loads(raw)
print('FPbase protein count', len(prots), flush=True)

target_ex=505
target_em=610
idset=set(ids)
for p in prots:
    states=p.get('states',[])
    pdb_ids=set(p.get('pdb',[]) or [])
    for st in states:
        ex=st.get('ex_max')
        em=st.get('em_max')
        if ex==target_ex or em==target_em:
            print('FP match:', p.get('name'), 'slug', p.get('slug'), 'pdb', pdb_ids, 'ex', ex, 'em', em, 'seqlen', len(p.get('seq','')), 'uuid', p.get('uuid'), flush=True)
            if pdb_ids & idset:
                print('  *** PDB overlap:', pdb_ids & idset, flush=True)
                print('  seq:', p.get('seq','')[:80], flush=True)

# Also list all FPbase proteins with PDB overlap regardless of ex/em
print('\nFPbase proteins with PDB overlap:', flush=True)
for p in prots:
    pdb_ids=set(p.get('pdb',[]) or [])
    if pdb_ids & idset:
        states=p.get('states',[])
        print(p.get('name'), 'slug', p.get('slug'), 'pdb', pdb_ids & idset, 'states', [(st.get('ex_max'),st.get('em_max')) for st in states], 'seqlen', len(p.get('seq','')), flush=True)

# Search RCSB for ligand by SMILES
smiles='Nc3nc(OCc1ccccc1)c2nc[nH]c2n3'
print('\nSearching RCSB for SMILES:', smiles, flush=True)
search_url='https://search.rcsb.org/rcsbsearch/v2/query?json=' + urllib.parse.quote(json.dumps({
  "query": {
    "type": "terminal",
    "service": "chemical",
    "parameters": {
      "value": smiles,
      "type": "descriptor",
      "match_type": "exact"
    }
  },
  "return_type": "entry",
  "request_options": {"results_content_type": ["experimental"], "paginate": {"start": 0, "rows": 25}}
}))
try:
    req=urllib.request.Request(search_url, headers={'User-Agent':'Mozilla/5.0'})
    resp=urllib.request.urlopen(req, timeout=30).read().decode('utf-8','replace')
    print('Search response:', resp[:3000], flush=True)
except Exception as e:
    print('SMILES search ERR', repr(e), flush=True)
    # Try simpler chemical search
    for desc_type in ['smiles','inchi','inchikey']:
        try:
            q={"query":{"type":"terminal","service":"chemical","parameters":{"value":smiles,"type":"descriptor","match_type":"exact"}},"return_type":"entry","request_options":{"results_content_type":["experimental"],"paginate":{"start":0,"rows":25}}}
            su='https://search.rcsb.org/rcsbsearch/v2/query?json='+urllib.parse.quote(json.dumps(q))
            req=urllib.request.Request(su, headers={'User-Agent':'Mozilla/5.0'})
            resp=urllib.request.urlopen(req, timeout=30).read().decode('utf-8','replace')
            print('desc_type', desc_type, resp[:2000], flush=True)
            break
        except Exception as e2:
            print('desc_type', desc_type, 'ERR', repr(e2), flush=True)
